import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';

// Pages
import Login from './pages/Login';

// TODO: Import Layouts เมื่อสร้างเสร็จ
// import { CustomerLayout } from './components/layout/customer';
// import { InsuranceLayout } from './components/layout/insurance';
// import { GarageLayout } from './components/layout/garage';

// TODO: Import Pages เมื่อสร้างเสร็จ
// import { Dashboard, ClaimList, ClaimDetail } from './pages/customer';
// import { ActiveClaims, CreateClaim } from './pages/insurance';
// import { GarageDashboard, GarageRepairs } from './pages/garage';

/**
 * App Component - Main Router
 * 
 * Routes:
 * - / - Redirect to Login
 * - /login - Login Page ✅
 * - /customer/* - Customer Portal (TODO)
 * - /insurance/* - Insurance Company Portal (TODO)
 * - /garage/* - Garage Portal (TODO)
 * 
 * TODO: Backend Integration
 * - เพิ่ม Protected Routes ที่ตรวจสอบ authentication
 * - Redirect ไปหน้า login ถ้ายังไม่ได้ login
 * - Redirect ไปหน้าที่เหมาะสมตาม role
 */
function App() {
  return (
    <Router>
      <Routes>
        {/* Root - Redirect to Login */}
        <Route path="/" element={<Navigate to="/login" replace />} />

        {/* Login Page */}
        <Route path="/login" element={<Login />} />

        {/* Customer Portal - TODO: Implement */}
        {/* <Route path="/customer" element={<CustomerLayout />}>
          <Route index element={<Dashboard />} />
          <Route path="claims" element={<ClaimList />} />
          <Route path="claims/:id" element={<ClaimDetail />} />
        </Route> */}

        {/* Insurance Portal - TODO: Implement */}
        {/* <Route path="/insurance" element={<InsuranceLayout />}>
          <Route index element={<ActiveClaims />} />
          <Route path="claims/create" element={<CreateClaim />} />
        </Route> */}

        {/* Garage Portal - TODO: Implement */}
        {/* <Route path="/garage" element={<GarageLayout />}>
          <Route index element={<GarageDashboard />} />
        </Route> */}

        {/* 404 Not Found */}
        <Route path="*" element={
          <div className="flex items-center justify-center min-h-screen bg-neutral-50">
            <div className="text-center">
              <h1 className="text-6xl font-bold text-neutral-300 mb-4">404</h1>
              <p className="text-xl text-neutral-500 mb-6">ไม่พบหน้าที่คุณต้องการ</p>
              <a href="/login" className="btn-primary inline-flex items-center gap-2">
                <span className="material-icons-round">home</span>
                <span>กลับหน้าหลัก</span>
              </a>
            </div>
          </div>
        } />
      </Routes>
    </Router>
  );
}

export default App;
